import{_ as o,a0 as a,w as l,s as c,ao as r,I as n,x as e,a1 as i,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"如何在 CentOS 8/RHEL 8 上安装和使用 Cockpit | LCTT x X-CMD","titleTemplate":false,"description":"如何在 CentOS 8/RHEL 8 上安装和使用 Cockpit | LCTT (201910) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 CentOS 8/RHEL 8 上安装和使用 Cockpit | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 CentOS 8/RHEL 8 上安装和使用 Cockpit | LCTT (201910) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201910/20190929 How to Install and Use Cockpit on CentOS 8 - RHEL 8","title":"如何在 CentOS 8/RHEL 8 上安装和使用 Cockpit","tag":"201910","desc":""},"relativePath":"201910/20190929 How to Install and Use Cockpit on CentOS 8 - RHEL 8.md","filePath":"[post].md"}'),d={name:"201910/20190929 How to Install and Use Cockpit on CentOS 8 - RHEL 8.md"};function h(k,t,g,u,C,m){const s=a("Link");return l(),c("div",null,[t[15]||(t[15]=r(`<h1 id="如何在-centos-8-rhel-8-上安装和使用-cockpit" tabindex="-1">如何在 CentOS 8/RHEL 8 上安装和使用 Cockpit <a class="header-anchor" href="#如何在-centos-8-rhel-8-上安装和使用-cockpit" aria-label="Permalink to “如何在 CentOS 8/RHEL 8 上安装和使用 Cockpit”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/201910/12/093405gb8hv3exdbsdyfda.jpg" alt=""></p><p>Cockpit 是一个基于 Web 的服务器管理工具，可用于 CentOS 和 RHEL 系统。最近发布的 CentOS 8 和 RHEL 8，其中 cockpit 是默认的服务器管理工具。它的软件包在默认的 CentOS 8 和 RHEL 8 仓库中就有。Cockpit 是一个有用的基于 Web 的 GUI 工具，系统管理员可以通过该工具监控和管理 Linux 服务器，它还可用于管理服务器、容器、虚拟机中的网络和存储，以及检查系统和应用的日志。</p><p>在本文中，我们将演示如何在 CentOS 8 和 RHEL 8 中安装和设置 Cockpit。</p><h3 id="在-centos-8-rhel-8-上安装和设置cockpit" tabindex="-1">在 CentOS 8/RHEL 8 上安装和设置Cockpit <a class="header-anchor" href="#在-centos-8-rhel-8-上安装和设置cockpit" aria-label="Permalink to “在 CentOS 8/RHEL 8 上安装和设置Cockpit”">​</a></h3><p>登录你的 CentOS 8/RHEL 8，打开终端并执行以下 <code>dnf</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# dnf install cockpit -y</span></span></code></pre></div><p>运行以下命令启用并启动 cockpit 服务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# systemctl start cockpit.socket</span></span>
<span class="line"><span>[root@linuxtechi ~]# systemctl enable cockpit.socket</span></span></code></pre></div><p>使用以下命令在系统防火墙中允许 Cockpit 端口：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# firewall-cmd --permanent --add-service=cockpit</span></span>
<span class="line"><span>[root@linuxtechi ~]# firewall-cmd --reload</span></span></code></pre></div><p>验证 cockpit 服务是否已启动和运行，执行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# systemctl status cockpit.socket</span></span>
<span class="line"><span>[root@linuxtechi ~]# ss -tunlp | grep cockpit</span></span>
<span class="line"><span>[root@linuxtechi ~]# ps auxf|grep cockpit</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/cockpit-status-centos8-rhel8.jpg" alt="cockpit-status-centos8-rhel8"></p><h3 id="在-centos-8-rhel-8-上访问-cockpit" tabindex="-1">在 CentOS 8/RHEL 8 上访问 Cockpit <a class="header-anchor" href="#在-centos-8-rhel-8-上访问-cockpit" aria-label="Permalink to “在 CentOS 8/RHEL 8 上访问 Cockpit”">​</a></h3><p>正如我们在上面命令的输出中看到的，cockpit 正在监听 tcp 9090 端口，打开你的 Web 浏览器并输入 url：<code>https://&lt;Your-CentOS8/RHEL8-System-IP&gt;:9090</code>。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/CentOS8-cockpit-login-screen.jpg" alt="CentOS8-cockpit-login-screen"></p><p>RHEL 8 中的 Cockpit 登录页面：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/RHEL8-Cockpit-Login-Screen.jpg" alt="RHEL8-Cockpit-Login-Screen"></p><p>使用有管理员权限的用户名，或者我们也可以使用 root 用户的密码登录。如果要将管理员权限分配给任何本地用户，请执行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# usermod -G wheel pkumar</span></span></code></pre></div><p>这里 <code>pkumar</code> 是我的本地用户，</p><p>在输入用户密码后，选择 “Reuse my password for privileged tasks”，然后单击 “Log In”，然后我们看到以下页面：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/cockpit-dashboard-centos8.jpg" alt="cockpit-dashboard-centos8"></p><p>在左侧栏上，我们可以看到可以通过 cockpit GUI 监控和配置的内容，</p><p>假设你要检查 CentOS 8/RHEL 8 中是否有任何可用更新，请单击 “System Updates”：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Software-Updates-Cockpit-GUI-CentOS8-RHEL8.jpg" alt="Software-Updates-Cockpit-GUI-CentOS8-RHEL8"></p><p>要安装所有更新，点击 “Install All Updates”：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Install-Software-Updates-CentOS8-RHEL8.jpg" alt="Install-Software-Updates-CentOS8-RHEL8"></p><p>如果想要修改网络并要添加 Bond 接口和网桥，请单击 “Networking”：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Networking-Cockpit-Dashboard-CentOS8-RHEL8.jpg" alt="Networking-Cockpit-Dashboard-CentOS8-RHEL8"></p><p>如上所见，我们有创建 Bond 接口、网桥和 VLAN 标记接口的选项。</p><p>假设我们想创建一个 <code>br0</code> 网桥，并要为它添加 <code>enp0s3</code> 端口，单击 “Add Bridge”：</p><p>将网桥名称指定为 <code>br0</code>，将端口指定为 <code>enp0s3</code>，然后单击“Apply”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Add-Bridge-Cockpit-CentOS8-RHEL8.jpg" alt="Add-Bridge-Cockpit-CentOS8-RHEL8"></p><p>在下个页面，我们将看到该网桥处于活动状态，并且获得了与 enp0s3 接口相同的 IP：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/Bridge-Details-Cockpit-Dashboard-CentOS8-RHEL8.jpg" alt="Bridge-Details-Cockpit-Dashboard-CentOS8-RHEL8"></p><p>如果你想检查系统日志，单击 “Logs”，我们可以根据严重性查看日志：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/09/System-Logs-Cockpit-Dashboard-CentOS8-RHEL8.jpg" alt="System-Logs-Cockpit-Dashboard-CentOS8-RHEL8"></p><p>本文就是这些了，类似地，系统管理员可以使用 cockpit 的其他功能来监控和管理 CentOS 8 和 RHEL 8 服务器。如果这些步骤可以帮助你在 Linux 服务器上设置 cockpit，请在下面的评论栏分享你的反馈和意见。</p><hr>`,41)),n("p",null,[t[1]||(t[1]=e("via: ",-1)),i(s,{href:"https://www.linuxtechi.com/install-use-cockpit-tool-centos8-rhel8/"},{default:p(()=>[...t[0]||(t[0]=[e("https://www.linuxtechi.com/install-use-cockpit-tool-centos8-rhel8/",-1)])]),_:1})]),n("p",null,[t[6]||(t[6]=e("作者：",-1)),i(s,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:p(()=>[...t[2]||(t[2]=[e("Pradeep Kumar",-1)])]),_:1}),t[7]||(t[7]=e(" 选题：",-1)),i(s,{href:"https://github.com/lujun9972"},{default:p(()=>[...t[3]||(t[3]=[e("lujun9972",-1)])]),_:1}),t[8]||(t[8]=e(" 译者：",-1)),i(s,{href:"https://github.com/geekpi"},{default:p(()=>[...t[4]||(t[4]=[e("geekpi",-1)])]),_:1}),t[9]||(t[9]=e(" 校对：",-1)),i(s,{href:"https://github.com/wxy"},{default:p(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[12]||(t[12]=e("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原创编译，",-1)),i(s,{href:"https://linux.cn/"},{default:p(()=>[...t[11]||(t[11]=[e("Linux中国",-1)])]),_:1}),t[14]||(t[14]=e(" 荣誉推出",-1))])])}const f=o(d,[["render",h]]);export{L as __pageData,f as default};
